messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Low-Poly Humanoid Treadmill Cycle</title>
    <style>
        body {
            margin: 0;
            overflow: hidden;
            background-color: #222;
            font-family: Arial, Helvetica, sans-serif;
        }
        canvas {
            display: block;
        }
        .info {
            position: absolute;
            bottom: 10px;
            left: 10px;
            color: #aaa;
            font-size: 12px;
            background: rgba(0,0,0,0.5);
            padding: 4px 8px;
            border-radius: 4px;
            pointer-events: none;
        }
    </style>
</head>
<body>
    <div class="info">10s loop: stand (2s) → walk (3s) → run (3s) → stand (2s)</div>

    <script type="importmap">
        {
            "imports": {
                "three": "./three.module.js"
            }
        }
    </script>

    <script type="module">
        import * as THREE from 'three';

        // --- Setup scene, camera, renderer ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x2a2a3a);
        scene.fog = new THREE.Fog(0x2a2a3a, 20, 40);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(4, 2.5, 8);
        camera.lookAt(0, 1.2, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- Lights ---
        const ambient = new THREE.AmbientLight(0x404060);
        scene.add(ambient);

        const dirLight = new THREE.DirectionalLight(0xffeedd, 1.2);
        dirLight.position.set(3, 6, 4);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 512;
        dirLight.shadow.mapSize.height = 512;
        scene.add(dirLight);

        const fillLight = new THREE.DirectionalLight(0x4466ff, 0.3);
        fillLight.position.set(-2, 3, -3);
        scene.add(fillLight);

        // --- Ground (treadmill-style) ---
        const groundGeo = new THREE.BoxGeometry(8, 0.2, 3);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x3a3a4a, roughness: 0.8 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.position.set(0, -0.1, 0);
        ground.receiveShadow = true;
        scene.add(ground);

        // Treadmill side rails
        const railMat = new THREE.MeshStandardMaterial({ color: 0x5a5a6a });
        const railLeft = new THREE.Mesh(new THREE.BoxGeometry(8, 0.3, 0.15), railMat);
        railLeft.position.set(0, 0.1, -1.5);
        railLeft.castShadow = true;
        scene.add(railLeft);
        const railRight = new THREE.Mesh(new THREE.BoxGeometry(8, 0.3, 0.15), railMat);
        railRight.position.set(0, 0.1, 1.5);
        railRight.castShadow = true;
        scene.add(railRight);

        // --- Build low-poly humanoid ---
        // Use group for the whole figure, pivot at hips (y=1.0)
        const human = new THREE.Group();
        human.position.set(0, 0, 0);

        // Materials
        const skinMat = new THREE.MeshStandardMaterial({ color: 0x8a6a5a, roughness: 0.6 });
        const shirtMat = new THREE.MeshStandardMaterial({ color: 0x3a7a5a, roughness: 0.7 });
        const pantsMat = new THREE.MeshStandardMaterial({ color: 0x3a4a6a, roughness: 0.7 });
        const shoeMat = new THREE.MeshStandardMaterial({ color: 0x2a2a3a, roughness: 0.9 });

        // Torso
        const torso = new THREE.Mesh(new THREE.BoxGeometry(0.8, 1.0, 0.5), shirtMat);
        torso.position.set(0, 1.2, 0);
        torso.castShadow = true;
        human.add(torso);

        // Head
        const head = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.5, 0.5), skinMat);
        head.position.set(0, 1.9, 0.1);
        head.castShadow = true;
        human.add(head);

        // Hat/helmet (simple)
        const hat = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.2, 0.5), new THREE.MeshStandardMaterial({ color: 0x3a3a5a }));
        hat.position.set(0, 2.1, 0.1);
        hat.castShadow = true;
        human.add(hat);

        // Arms (left and right) - pivot at shoulder (y=1.6)
        // Left arm group
        const leftArmGroup = new THREE.Group();
        leftArmGroup.position.set(-0.5, 1.6, 0);
        const leftArm = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.8, 0.25), skinMat);
        leftArm.position.set(-0.1, -0.4, 0);
        leftArm.castShadow = true;
        leftArmGroup.add(leftArm);
        human.add(leftArmGroup);

        // Right arm group
        const rightArmGroup = new THREE.Group();
        rightArmGroup.position.set(0.5, 1.6, 0);
        const rightArm = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.8, 0.25), skinMat);
        rightArm.position.set(0.1, -0.4, 0);
        rightArm.castShadow = true;
        rightArmGroup.add(rightArm);
        human.add(rightArmGroup);

        // Legs (left and right) - pivot at hip (y=1.0)
        // Left leg group
        const leftLegGroup = new THREE.Group();
        leftLegGroup.position.set(-0.25, 1.0, 0);
        const leftLeg = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.9, 0.25), pantsMat);
        leftLeg.position.set(0, -0.45, 0);
        leftLeg.castShadow = true;
        leftLegGroup.add(leftLeg);
        // Shoe
        const leftShoe = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.2, 0.4), shoeMat);
        leftShoe.position.set(0, -0.9, 0.1);
        leftShoe.castShadow = true;
        leftLegGroup.add(leftShoe);
        human.add(leftLegGroup);

        // Right leg group
        const rightLegGroup = new THREE.Group();
        rightLegGroup.position.set(0.25, 1.0, 0);
        const rightLeg = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.9, 0.25), pantsMat);
        rightLeg.position.set(0, -0.45, 0);
        rightLeg.castShadow = true;
        rightLegGroup.add(rightLeg);
        // Shoe
        const rightShoe = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.2, 0.4), shoeMat);
        rightShoe.position.set(0, -0.9, 0.1);
        rightShoe.castShadow = true;
        rightLegGroup.add(rightShoe);
        human.add(rightLegGroup);

        // Add human to scene
        scene.add(human);

        // --- Animation timing ---
        // Cycle: stand (2s), walk (3s), run (3s), stand (2s) = 10s total
        const CYCLE_DURATION = 10.0;
        const STAND1_DURATION = 2.0;
        const WALK_DURATION = 3.0;
        const RUN_DURATION = 3.0;
        const STAND2_DURATION = 2.0;

        // --- Animation state ---
        let clock = new THREE.Clock();

        // Helper to compute phase in [0,1] for a given interval
        function cyclePhase(time, start, duration) {
            if (duration <= 0) return 0;
            const local = time - start;
            return (local % duration) / duration;
        }

        // --- Animation loop ---
        function animate() {
            const elapsed = clock.getElapsedTime();
            const t = elapsed % CYCLE_DURATION;

            // Determine current phase
            let mode = 'stand';
            let phase = 0;
            let leanAngle = 0; // radians for torso/body forward lean

            if (t < STAND1_DURATION) {
                // Stand still
                mode = 'stand';
                phase = 0;
                leanAngle = 0;
            } else if (t < STAND1_DURATION + WALK_DURATION) {
                // Walk
                mode = 'walk';
                phase = cyclePhase(t, STAND1_DURATION, WALK_DURATION);
                leanAngle = 0.04; // slight forward lean
            } else if (t < STAND1_DURATION + WALK_DURATION + RUN_DURATION) {
                // Run
                mode = 'run';
                phase = cyclePhase(t, STAND1_DURATION + WALK_DURATION, RUN_DURATION);
                leanAngle = 0.12; // more forward lean
            } else {
                // Stand still again
                mode = 'stand';
                phase = 0;
                leanAngle = 0;
            }

            // --- Compute limb angles ---
            // Arm swing: opposite to legs. Walk: moderate, Run: large and faster.
            let armAngleLeft = 0;
            let armAngleRight = 0;
            let legAngleLeft = 0;
            let legAngleRight = 0;
            let armSpeedFactor = 1;
            let legSpeedFactor = 1;
            let maxArmAngle = 0.2; // radians
            let maxLegAngle = 0.25; // radians

            if (mode === 'walk') {
                // Walk: 2 steps per cycle? Use phase 0..1 for one full stride (left+right)
                // Left leg forward when phase 0-0.5, right leg forward when 0.5-1.0
                // Arms opposite
                const legPhase = phase * 2; // 0..2
                const armPhase = legPhase + 1; // shifted
                legAngleLeft = Math.sin(legPhase * Math.PI) * 0.35; // walk amplitude
                legAngleRight = Math.sin((legPhase + 1) * Math.PI) * 0.35;
                armAngleLeft = Math.sin(armPhase * Math.PI) * 0.25;
                armAngleRight = Math.sin((armPhase + 1) * Math.PI) * 0.25;
                maxLegAngle = 0.35;
                maxArmAngle = 0.25;
                legSpeedFactor = 1.0;
                armSpeedFactor = 1.0;
            } else if (mode === 'run') {
                // Run: faster, larger swings. Use phase 0..1 for full cycle, but double frequency
                const legPhase = phase * 4; // 0..4
                const armPhase = legPhase + 2; // shift
                legAngleLeft = Math.sin(legPhase * Math.PI) * 0.55;
                legAngleRight = Math.sin((legPhase + 1) * Math.PI) * 0.55;
                armAngleLeft = Math.sin(armPhase * Math.PI) * 0.45;
                armAngleRight = Math.sin((armPhase + 1) * Math.PI) * 0.45;
                maxLegAngle = 0.55;
                maxArmAngle = 0.45;
                legSpeedFactor = 2.0;
                armSpeedFactor = 2.0;
            } else {
                // Stand: all zero
                legAngleLeft = 0;
                legAngleRight = 0;
                armAngleLeft = 0;
                armAngleRight = 0;
            }

            // Apply rotations to limbs (pivot groups)
            // Arms: rotate around Z (forward/back) - positive Z is forward? 
            // In three.js, Z is forward if camera looks at -Z? Actually we set camera looking at origin from +Z, so Z points away from camera? 
            // We want arms swinging forward/back (around X axis? Actually side view: forward is +Z, but for side-on camera at +Z, we see XZ plane. 
            // To swing arms forward/back, rotate around X axis? No: forward/back is along Z, so rotation around X tilts forward/back? 
            // Let's use rotation around X for arms and legs: positive X rotation moves limb forward (towards +Z) if pivot at shoulder/hip? 
            // Test: For left arm at (-0.5,1.6,0), rotating around X positive moves the arm tip (negative Y) towards +Z? Actually rotation around X: Y goes to Z, Z goes to -Y. So positive X rotation moves the arm forward (Z+) if arm extends downward (Y-). Good.
            // So use rotation.x for limb swing.
            leftArmGroup.rotation.x = armAngleLeft;
            rightArmGroup.rotation.x = armAngleRight;

            leftLegGroup.rotation.x = legAngleLeft;
            rightLegGroup.rotation.x = legAngleRight;

            // Torso/head lean (forward lean) - rotate whole human group slightly around X to lean forward
            // But we want the lean to affect torso and head, not legs (legs stay vertical). 
            // Better: apply lean to torso and head only, or rotate whole human and counter-rotate legs? 
            // For simplicity, rotate torso, head, hat, arms? But arms pivot at shoulder, so if torso rotates, arms rotate too. 
            // Let's rotate torso and head and hat, but keep legs upright. 
            // We'll store references to torso, head, hat, and arm groups? But arm groups are children of human, so rotating torso won't rotate arms. 
            // Actually torso is a child of human, but arms are children of human, not torso. So we can rotate torso and head independently.
            // We want a forward lean of the upper body. So rotate torso, head, hat around X axis by leanAngle.
            torso.rotation.x = leanAngle;
            head.rotation.x = leanAngle;
            hat.rotation.x = leanAngle;

            // Also maybe arms should lean with torso? But they are attached to shoulder, so if torso rotates, shoulder position changes. 
            // For simplicity, we rotate arms slightly too to match lean? Not necessary for low-poly.
            // We'll also rotate the whole human group slightly? No, that would move legs.

            // --- Side-on camera: we want the figure facing +Z (towards camera) or -Z? 
            // The camera is at +Z looking at origin, so the figure's front should be +Z to be visible side-on? 
            // Actually side-on means we see the side profile, so the figure should face either left or right (X direction). 
            // For treadmill, the figure faces forward (Z) and we see side view. So we want the figure's front to be +Z or -Z? 
            // If camera is at +Z looking at origin, the figure facing +Z would be facing camera (front view). 
            // To see side view, we should rotate human so it faces along X? But limbs swing forward/back along Z, so side view shows the swing. 
            // Let's keep human facing +Z (default), and camera at +Z but offset in X to see side? Actually camera at (4,2.5,8) looks at (0,1.2,0) so it sees the front-right diagonal. 
            // To make it side-on, we can rotate the human to face along X? But then limb swings along Z would be seen from the side? 
            // Better: rotate the human so its front is along +X? But then limb swing along Z would be perpendicular to view? 
            // Actually side-on means we see the profile: the figure's left/right side. So the figure should face along Z (forward), and we view from +X or -X. 
            // Let's place camera at (8,2,0) looking at (0,1.2,0) to see side profile. But we already set camera at (4,2.5,8). 
            // Let's adjust camera to be more side-on: set camera position to (8, 2.5, 0) and look at (0,1.2,0). 
            // I'll change camera in the setup. Let's modify to side view.
            camera.position.set(8, 2.5, 0);
            camera.lookAt(0, 1.2, 0);

            // Now the figure faces +Z, and camera is on +X side, so we see side profile. 
            // Limb swings along Z (forward/back) will be visible as forward/back motion.

            // --- Render ---
            renderer.render(scene, camera);
        }

        // Start animation loop
        renderer.setAnimationLoop(animate);

        // Handle resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Note: The animation starts immediately because setAnimationLoop is called.
    </script>
</body>
</html>
```
